#[path="C:/Users/fallo/Documents/ChatGPT/Freecad/genewars-preflight/rust/crates/genewars-runtime/src/creature_pick.rs"]mod pick;use pick::*;use std::io::{Read,Write};fn main(){let mut s=String::new();std::io::stdin().read_to_string(&mut s).unwrap();let mut out=String::new();for line in s.lines(){let v:Vec<i32>=line.split_whitespace().map(|x|x.parse().unwrap()).collect();let c=PickComponent{offset:[v[3]as i16,-v[3]as i16],sprite_dimensions:Some([v[5]as u8,v[6]as u8]),flags:v[4]as u8};let mut last=c;if v[7]!=0{last.sprite_dimensions=None;}let cs=[c,last];let index=hit_frame(&cs,[v[8],v[9]],[v[10],v[11]],v[0]as u16).unwrap().map(i32::from).unwrap_or(-1);let hit=hit_mule(&cs,MulePickInput{scale76:v[1]as u8,scale77:v[2]as u8,ground:[v[12]as i16,v[13]as i16],point:[v[10]as i16,v[11]as i16],relative_height:v[14]}).unwrap();out.push_str(&format!("{} {}\n",index,u8::from(hit)));}assert_eq!(hit_frame(&[],[0,0],[0,0],256),Err(PickError::EmptyFrame));assert_eq!(hit_frame(&vec![PickComponent{offset:[0,0],sprite_dimensions:None,flags:0};256],[0,0],[0,0],256),Err(PickError::TooManyComponents));assert_eq!(hit_frame(&[PickComponent{offset:[0,0],sprite_dimensions:None,flags:0}],[0,0],[0,0],257),Err(PickError::Factor));std::io::stdout().write_all(out.as_bytes()).unwrap();}